import { cva, type VariantProps } from 'class-variance-authority';
import { cn } from '@/lib/utils';

const buttonVariants = cva(
  'inline-flex items-center justify-center rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2',
  {
    variants: {
      variant: {
        default: 'bg-blue-600 text-white hover:bg-blue-700',
        outline: 'border border-gray-300 bg-white hover:bg-gray-50',
        ghost: 'hover:bg-gray-100',
      },
      size: { default: 'h-10 px-4', sm: 'h-8 px-3', lg: 'h-11 px-6' },
    },
    defaultVariants: { variant: 'default', size: 'default' },
  },
);

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement>, VariantProps<typeof buttonVariants> {}

export function Button{ 19 }({ className, variant, size, ...props }: ButtonProps) {
  return <button className={cn(buttonVariants({ variant, size }), className)} {...props} />;
}

import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react';

export const api6 = createApi({
  reducerPath: 'api6',
  baseQuery: fetchBaseQuery({ baseUrl: '/api' }),
  tagTypes: ['Item'],
  endpoints: (build) => ({
    listItems: build.query<{ id: string }[], void>({
      query: () => '/items-6',
      providesTags: ['Item'],
    }),
    addItem: build.mutation<void, { name: string }>({
      query: (body) => ({ url: '/items-6', method: 'POST', body }),
      invalidatesTags: ['Item'],
    }),
  }),
});

export const { useListItemsQuery, useAddItemMutation } = api6;
